import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// 资料站标志。能用 simple-icons（CC0）的用图形；TheTVDB 用站点标志。
/// 没有独立图形的站用短标。Emby 按 ProviderIds 现生成 ExternalUrls，域名决定图标。
enum ProviderMark {
  imdb(Color(0xFFF5C518), svg: _imdb),
  tmdb(Color(0xFF01D277), svg: _tmdb),
  trakt(Color(0xFFED1C24), svg: _trakt),
  tvdb(Color(0xFF1B7D3D), svg: _tvdb, tint: false),
  musicbrainz(Color(0xFFBA478F), svg: _musicbrainz),
  anilist(Color(0xFF02A9FF), svg: _anilist),
  myAnimeList(Color(0xFF2E51A2), svg: _myanimelist),
  douban(Color(0xFF00B51D), svg: _douban),
  simkl(Color(0xFFF2F2F2), svg: _simkl),
  kitsu(Color(0xFFFD755C), svg: _kitsu),
  tvmaze(Color(0xFFE3262E), label: 'maze'),
  audioDb(Color(0xFFE85D04), label: 'ADB'),
  anidb(Color(0xFF3D7EA6), label: 'aniDB'),
  bangumi(Color(0xFFF09199), label: 'bgm');

  const ProviderMark(this.color, {this.svg, this.tint = true, this.label});

  final Color color;
  final String? svg;
  final bool tint;
  final String? label;

  static ProviderMark? match(String name, String url) {
    final host = Uri.tryParse(url)?.host.toLowerCase() ?? '';
    final label = name.toLowerCase();
    if (_hit(host, label, 'imdb')) return ProviderMark.imdb;
    if (_hit(host, label, 'themoviedb') ||
        _hit(host, label, 'tmdb') ||
        label.contains('moviedb')) {
      return ProviderMark.tmdb;
    }
    if (_hit(host, label, 'trakt')) return ProviderMark.trakt;
    if (_hit(host, label, 'thetvdb') || _hit(host, label, 'tvdb')) {
      return ProviderMark.tvdb;
    }
    if (_hit(host, label, 'tvmaze')) return ProviderMark.tvmaze;
    if (_hit(host, label, 'musicbrainz')) return ProviderMark.musicbrainz;
    if (_hit(host, label, 'theaudiodb') || _hit(host, label, 'audiodb')) {
      return ProviderMark.audioDb;
    }
    if (_hit(host, label, 'anilist')) return ProviderMark.anilist;
    if (_hit(host, label, 'myanimelist')) return ProviderMark.myAnimeList;
    if (_hit(host, label, 'anidb')) return ProviderMark.anidb;
    if (_hit(host, label, 'simkl')) return ProviderMark.simkl;
    if (_hit(host, label, 'douban') || label.contains('豆瓣')) {
      return ProviderMark.douban;
    }
    if (host.contains('bgm.tv') ||
        host.contains('bangumi') ||
        label.contains('bangumi') ||
        label.contains('番组')) {
      return ProviderMark.bangumi;
    }
    if (_hit(host, label, 'kitsu')) return ProviderMark.kitsu;
    return null;
  }

  static bool _hit(String host, String label, String token) {
    return host.contains(token) || label.contains(token);
  }

  String get shortName => switch (this) {
    ProviderMark.imdb => 'IMDb',
    ProviderMark.tmdb => 'TMDB',
    ProviderMark.trakt => 'Trakt',
    ProviderMark.tvdb => 'TVDB',
    ProviderMark.musicbrainz => 'MusicBrainz',
    ProviderMark.anilist => 'AniList',
    ProviderMark.myAnimeList => 'MAL',
    ProviderMark.douban => '豆瓣',
    ProviderMark.simkl => 'Simkl',
    ProviderMark.kitsu => 'Kitsu',
    ProviderMark.tvmaze => 'TVmaze',
    ProviderMark.audioDb => 'AudioDB',
    ProviderMark.anidb => 'AniDB',
    ProviderMark.bangumi => 'Bangumi',
  };
}

class ProviderMarkIcon extends StatelessWidget {
  const ProviderMarkIcon({
    super.key,
    required this.mark,
    this.size = 22,
    this.color,
  });

  final ProviderMark mark;
  final double size;

  /// 覆盖品牌色的单色呈现;低调场景(如详情页外链区)传主题色,
  /// 不传时保留品牌色 tint/文字。
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final svg = mark.svg;
    if (svg != null) {
      return SvgPicture.string(
        svg,
        height: size,
        fit: BoxFit.contain,
        colorFilter: mark.tint
            ? ColorFilter.mode(color ?? mark.color, BlendMode.srcIn)
            : null,
      );
    }
    return Text(
      mark.label ?? '',
      style: TextStyle(
        color: color ?? mark.color,
        fontSize: 11,
        fontWeight: FontWeight.w700,
        height: 1,
      ),
    );
  }
}

